/**
 * vocabulary -- the schema.org vocabulary as data (data/schema-vocabulary.json, generated by
 * scripts/build-vocabulary.mjs from the published schemaorg-current-https.jsonld) and a validator that
 * holds a JSON-LD node to it: a known `@type`; every property a property of that type or one of its
 * ancestors (schema.org's `domainIncludes`); a nested node's type within the property's range (or a
 * subtype of it); and literals of the right form for Date, DateTime, URL, Number, Integer and Boolean
 * ranges. A property schema.org does not define is ignored by consumers, so it is reported.
 */
import { readFileSync } from "node:fs";

let loaded;
export function schemaVocabulary() {
  loaded ??= JSON.parse(readFileSync(new URL("../data/schema-vocabulary.json", import.meta.url), "utf8"));
  return loaded;
}

/** `type` and all its ancestors. */
export function ancestorsOf(type, vocabulary = schemaVocabulary()) {
  const seen = new Set();
  const visit = (t) => {
    if (seen.has(t)) return;
    seen.add(t);
    for (const parent of vocabulary.types[t]?.parents ?? []) visit(parent);
  };
  visit(type);
  return seen;
}

/**
 * Terms the schema.org JSON-LD context defines that are not RDF properties of the vocabulary graph
 * (Google's structured-data documentation depends on `query-input`).
 */
const CONTEXT_TERMS = Object.freeze({ "query-input": { domains: ["SearchAction"], ranges: ["Text", "PropertyValueSpecification"] } });

const bare = (value) => String(value).replace(/^https?:\/\/schema\.org\//u, "").replace(/^schema:/u, "");
const ISO = /^\d{4}-\d{2}-\d{2}(?:[Tt]\d{2}:\d{2}(?::\d{2}(?:\.\d+)?)?(?:[Zz]|[+-]\d{2}:\d{2})?)?$/u;

function literalProblem(value, ranges) {
  const only = (names) => ranges.every((r) => names.includes(r));
  if (typeof value === "object" && value !== null) return undefined;
  if (only(["Date", "DateTime"])) return typeof value === "string" && ISO.test(value) ? undefined : "an ISO 8601 date or date-time";
  if (only(["URL"])) { try { new URL(String(value)); return undefined; } catch { return "an absolute URL"; } }
  if (only(["Integer"])) return Number.isInteger(Number(value)) ? undefined : "an integer";
  if (only(["Number", "Integer", "Float"])) return Number.isFinite(Number(value)) ? undefined : "a number";
  if (only(["Boolean"])) return typeof value === "boolean" || value === "True" || value === "False" ? undefined : "a boolean";
  return undefined;
}

function contextOk(context) {
  const entries = [].concat(context ?? []);
  return entries.some((c) => c === "https://schema.org" || c === "https://schema.org/" || c === "http://schema.org" || c === "http://schema.org/" || (typeof c === "object" && c !== null && (c["@vocab"] === "https://schema.org/" || c["@vocab"] === "http://schema.org/")));
}

/**
 * Validate a node (or an `@graph`, or an array of nodes). Returns `{ valid, problems }` where each
 * problem is `{ path, message }`.
 */
export function validateSchemaNode(node, { vocabulary = schemaVocabulary(), requireContext = true } = {}) {
  const problems = [];
  const report = (path, message) => problems.push({ path, message });
  const visit = (value, path, inheritedContext) => {
    if (Array.isArray(value)) { value.forEach((v, i) => visit(v, `${path}[${i}]`, inheritedContext)); return; }
    if (value === null || typeof value !== "object") return;
    const context = value["@context"] ?? inheritedContext;
    if (value["@graph"] !== undefined) {
      if (requireContext && !contextOk(context)) report(path, "no schema.org @context");
      visit(value["@graph"], `${path}/@graph`, context);
      return;
    }
    const types = [].concat(value["@type"] ?? []).map(bare);
    if (types.length === 0) { report(path, "a node needs an @type"); return; }
    if (requireContext && !contextOk(context)) report(path, "no schema.org @context");
    const unknown = types.filter((t) => vocabulary.types[t] === undefined);
    for (const t of unknown) report(path, `unknown type ${t}`);
    const known = types.filter((t) => vocabulary.types[t] !== undefined);
    const classes = new Set(known.flatMap((t) => [...ancestorsOf(t, vocabulary)]));
    for (const [key, raw] of Object.entries(value)) {
      if (key.startsWith("@")) continue;
      const property = vocabulary.properties[key] ?? CONTEXT_TERMS[key];
      if (property === undefined) { report(`${path}/${key}`, `${key} is not a schema.org property`); continue; }
      if (known.length > 0 && !property.domains.some((d) => classes.has(d))) report(`${path}/${key}`, `${key} does not apply to ${known.join(", ")}`);
      for (const v of [].concat(raw)) {
        if (v !== null && typeof v === "object") {
          const nestedTypes = [].concat(v["@type"] ?? []).map(bare).filter((t) => vocabulary.types[t] !== undefined);
          if (nestedTypes.length > 0 && !nestedTypes.some((t) => [...ancestorsOf(t, vocabulary)].some((a) => property.ranges.includes(a)))) report(`${path}/${key}`, `${nestedTypes.join(", ")} is not a valid value of ${key}`);
          visit(v, `${path}/${key}`, context);
        } else {
          const bad = literalProblem(v, property.ranges);
          if (bad) report(`${path}/${key}`, `${key} should be ${bad}`);
        }
      }
    }
  };
  visit(node, "", undefined);
  return { valid: problems.length === 0, problems };
}
